def _glomit(self, target, scope):
    result = target
    for child in self.children:
        result = scope[glom](result, child, scope)
    return result

def _glomit(self, target, scope):
    for child in self.children[:-1]:
        try:
            return scope[glom](target, child, scope)
        except GlomError:
            pass
    return scope[glom](target, self.children[-1], scope)

def glomit(self, target, scope):
    try:
        scope[glom](target, self.child, scope)
    except GlomError:
        return target
    else:
        raise MatchError("child shouldn't have passed", self.child)

def glomit(self, target, scope):
    if target:
        return target
    raise MatchError("{0!r} not truthy", target)
